recipes.code:
{
  "inputs": [
    {
      "id": "who-client-secret",
      "type": "promptString",
      "description": "WHO ICD-11 API Client Secret. Required only for ICD-11 tools.",
      "password": true
    }
  ],
  "servers": {
    "medical-terminologies": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "medical-terminologies-mcp@1.5.7"
      ],
      "env": {
        "WHO_CLIENT_ID": "<who-client-id>",
        "WHO_CLIENT_SECRET": "${input:who-client-secret}",
        "WHO_ICD11_RELEASE_ID": "<who-icd11-release-id>",
        "ENABLE_SNOMED_TOOLS": "<enable-snomed-tools>",
        "SNOMED_BASE_URL": "<snomed-base-url>",
        "SNOMED_LANGUAGE": "<snomed-language>",
        "LOG_LEVEL": "<log-level>"
      }
    }
  }
}
